@layer components {
  /* Surfaces */
  .card {
    @apply rounded-2xl border border-white/[0.06] bg-navy-900/70 p-6 backdrop-blur-md;
    box-shadow: 0 1px 0 0 rgb(255 255 255 / 0.03) inset, 0 8px 32px -12px rgb(0 0 0 / 0.5);
  }
  .card-hover {
    @apply transition-all duration-200 hover:border-brand-500/30 hover:bg-navy-850/80;
  }
  .glass {
    @apply rounded-2xl border border-white/[0.08] bg-white/[0.03] backdrop-blur-xl;
  }
  .glow-brand {
    box-shadow: 0 0 40px -8px rgb(111 71 245 / 0.35);
  }
  /* The auth-card glow ring — ported directly from Kodely's PromptHero
     "chasing light" ring (components/marketing/PromptHero.tsx +
     app/globals.css there), recoloured to Nxeon's blue -> violet -> cyan
     family instead of Kodely's pink/purple/orange. Same technique, kept
     intact rather than reinvented:
     - Each layer is a STATIC outer clipper (.glow-clip-a/-b, position, plain
       overflow:hidden, never transforms) containing one OVERSIZED inner
       rotator (.glow-spin-a/-b, a 200%-wide square via SPIN_SQUARE in
       AuthShell.tsx, centered) carrying the conic-gradient background. Only
       the inner rotator spins via plain `transform: rotate()`; being
       oversized, its corners sweeping outside a same-sized box never matter
       because the static outer clipper crops them at every angle.
     - The blur lives on the CLIP element, not the rotating child, because
       filters apply after the element's own overflow:hidden clipping — that
       ordering is what lets the light bleed softly past the clip's edge
       instead of surviving as a hard-edged ring.
     - The card sitting on top (relative z-10, opaque) covers the rotator's
       entire interior, leaving only the outer few px visible as a ring.
     - Entrance fade-in, then a slow ambient pulse picking up from the same
       opacity the fade-in settled on (no jump at the handoff). */
  @keyframes glow-spin {
    to {
      transform: rotate(360deg);
    }
  }
  .glow-spin-a {
    animation: glow-spin 9s linear infinite;
  }
  .glow-spin-b {
    animation: glow-spin 14s linear infinite reverse;
  }
  @keyframes glow-fade-in-a {
    from {
      opacity: 0;
      transform: scale(0.94);
    }
    to {
      opacity: 0.22;
      transform: scale(1);
    }
  }
  @keyframes glow-fade-in-b {
    from {
      opacity: 0;
      transform: scale(0.94);
    }
    to {
      opacity: 0.13;
      transform: scale(1);
    }
  }
  @keyframes glow-pulse-a {
    0%,
    100% {
      opacity: 0.22;
    }
    50% {
      opacity: 0.32;
    }
  }
  @keyframes glow-pulse-b {
    0%,
    100% {
      opacity: 0.13;
    }
    50% {
      opacity: 0.21;
    }
  }
  .glow-clip-a {
    animation:
      glow-fade-in-a 0.8s cubic-bezier(0.16, 1, 0.3, 1) both,
      glow-pulse-a 4.5s ease-in-out 0.8s infinite;
  }
  .glow-clip-b {
    animation:
      glow-fade-in-b 0.9s cubic-bezier(0.16, 1, 0.3, 1) 0.1s both,
      glow-pulse-b 6s ease-in-out 1s infinite;
  }
  @media (prefers-reduced-motion: reduce) {
    .glow-spin-a,
    .glow-spin-b {
      animation: none;
    }
    .glow-clip-a {
      animation: none;
      opacity: 0.22;
    }
    .glow-clip-b {
      animation: none;
      opacity: 0.13;
    }
  }
  /* Subtle outer glow for the deploy wizard's outer container — same violet→cyan
     brand pair as .hero-aura / DeployHub's tile glows, just restrained: a checkout
     flow, not a marketing hero. Self-contained (restates .card's own shadow layers
     plus two soft ambient glow layers) so it doesn't depend on CSS source order
     when applied alongside .card. */
  .wizard-shell {
    box-shadow:
      0 1px 0 0 rgb(255 255 255 / 0.03) inset,
      0 8px 32px -12px rgb(0 0 0 / 0.5),
      0 0 60px -22px rgb(111 71 245 / 0.35),
      0 0 90px -36px rgb(34 211 238 / 0.22);
  }

  /* Typography */
  .grad-text {
    @apply bg-gradient-to-r from-accent-blue via-brand-400 to-brand-500 bg-clip-text text-transparent;
  }
  .page-title {
    @apply text-2xl font-bold tracking-tight;
  }
  .section-label {
    @apply text-[11px] font-semibold uppercase tracking-[0.14em] text-slate-500;
  }

  /* Buttons */
  .btn-primary,
  .btn-secondary,
  .btn-danger,
  .btn-ghost,
  .btn-deploy {
    @apply inline-flex cursor-pointer items-center justify-center gap-2 rounded-xl px-4 py-2 text-sm font-semibold transition-all duration-150 disabled:cursor-not-allowed disabled:opacity-50;
  }
  .btn-primary {
    @apply bg-gradient-to-r from-accent-blue to-brand-500 text-white hover:brightness-110;
    box-shadow: 0 4px 20px -6px rgb(111 71 245 / 0.5);
  }
  /* The sleek, unified "Deploy" CTA used across every service page. Animated
     gradient-shift + a one-shot shimmer sweep on hover + an arrow nudge. */
  @keyframes btn-deploy-sweep {
    0% { transform: translateX(-130%) skewX(-12deg); }
    100% { transform: translateX(130%) skewX(-12deg); }
  }
  .btn-deploy {
    @apply relative overflow-hidden rounded-full px-5 text-white;
    background-image: linear-gradient(110deg, var(--color-brand-500), var(--color-accent-blue), var(--color-accent-cyan), var(--color-brand-500));
    background-size: 220% 100%;
    background-position: 0% 0;
    box-shadow: 0 8px 26px -8px rgb(111 71 245 / 0.55), inset 0 1px 0 0 rgb(255 255 255 / 0.18);
    transition: transform 0.2s ease, box-shadow 0.2s ease, background-position 0.6s ease;
  }
  .btn-deploy:hover {
    transform: translateY(-1px);
    background-position: 100% 0;
    box-shadow: 0 12px 34px -8px rgb(111 71 245 / 0.7), inset 0 1px 0 0 rgb(255 255 255 / 0.25);
  }
  .btn-deploy::before {
    content: "";
    position: absolute;
    top: 0;
    bottom: 0;
    left: 0;
    width: 60%;
    background: linear-gradient(90deg, transparent, rgb(255 255 255 / 0.38), transparent);
    transform: translateX(-130%) skewX(-12deg);
    pointer-events: none;
  }
  .btn-deploy:hover::before {
    animation: btn-deploy-sweep 0.75s ease;
  }
  .btn-deploy .dep-arrow {
    transition: transform 0.25s ease;
  }
  .btn-deploy:hover .dep-arrow {
    transform: translateX(3px);
  }
  @media (prefers-reduced-motion: reduce) {
    .btn-deploy,
    .btn-deploy:hover {
      transition: none;
    }
    .btn-deploy:hover::before {
      animation: none;
    }
    .btn-deploy:hover .dep-arrow {
      transform: none;
    }
  }
  .btn-secondary {
    @apply border border-white/10 bg-white/[0.04] text-slate-100 hover:border-white/20 hover:bg-white/[0.08];
  }
  .btn-danger {
    @apply border border-red-500/30 bg-red-500/10 text-red-300 hover:bg-red-500/20;
  }
  .btn-ghost {
    @apply text-slate-400 hover:bg-white/[0.05] hover:text-white;
  }

